/**
 * Turn a finished session log into an *episode*: the small, evidence-carrying
 * digest an extraction call can read.
 *
 * WHY NOT THE WHOLE LOG
 *
 * A finished session can be 15k events / 9 MB. Feeding it to a model to "find
 * skills" is both expensive and lossy in the wrong direction: the model drowns
 * in tool output and summarises the noise. What matters for capability memory is
 * (a) what the assistant concluded, (b) what failed and how, (c) which tools were
 * involved. Everything else stays in the log, reachable by seq — that is the
 * "facts are retrievable, capability is persisted" split.
 */

                               
               
              
              
 

                          
                   
                     
               
                                                                             
                                                   
                        
     
                                                 
    
                                                                                 
                                                                                 
                                                             
     
                           
                     
                                                                          
                    
 

/**
 * v0.32 P2: only a literal `kind: 'user'` is a HUMAN message.
 *
 * The old rule was a DENYLIST (`INJECTED_KIND`) of producer kinds observed so
 * far. DSH 0.2.2's `MessageSourceMap` already ships more producers than that
 * list covered — `working-directory`, `ptc-mode`, `tool-registry`,
 * `skill-invocation`, `compact-checkpoint`, `cordis-host-runner`,
 * `team-message`, `user-question-reply`, `goal`, `plan-mode`, `schedule`,
 * `session-reference`, `webhook` — and a denylist is guaranteed to miss the
 * NEXT `producerKind()` value too.
 *
 * The contract is one-sided: every producer kind is NOT the user. So the check
 * is an ALLOWLIST. A new kind is treated as injected by default (fail closed),
 * which is the only safe direction for something that may become a "skill".
 *
 * Note the 0.2.2 map's `user-rpc` source still carries `kind: 'user'` (with an
 * `rpcId`), so real user input is not lost.
 */
export const HUMAN_SOURCE_KIND = 'user'

export function isHumanSourceKind(kind         )          {
  return kind === HUMAN_SOURCE_KIND
}

function textOf(message         )         {
  if (message === null || typeof message !== 'object') return ''
  const content = (message                         ).content
  if (!Array.isArray(content)) return ''
  const parts           = []
  for (const block of content) {
    if (block !== null && typeof block === 'object' && (block       ).type === 'text' && typeof (block       ).text === 'string') {
      parts.push((block       ).text)
    }
  }
  return parts.join('\n').trim()
}

/**
 * The CLOSING BLOCK of an assistant message, not just its last paragraph.
 *
 * Measured on a real session: the final message carried the deliverable table
 * ("sqlite_crud.py — 连接管理 / 事务 / 分页 …"), the design decisions and the
 * lessons. Keeping only the last paragraph captured "no blockers" — the memory
 * then learned how the agent *reported*, not what it *built*. Three paragraphs
 * (bounded) keep the deliverable in view without turning the episode into a
 * transcript.
 */
function conclusionOf(text        )         {
  const paragraphs = text
    .split(/\n{2,}/u)
    .map((paragraph) => paragraph.replace(/\s+/gu, ' ').trim())
    .filter((paragraph) => paragraph.length >= 20 && !/^[-*]\s/u.test(paragraph))
  const tail = paragraphs.slice(-3).join('\n')
  if (tail.length > 0) return tail.slice(0, 1200)
  const firstLine = text.split(/\r?\n/u).map((line) => line.trim()).find((line) => line.length > 0) ?? ''
  return firstLine.slice(0, 1200)
}

export function segmentSession(sessionId        , log                        )          {
  const events = Array.isArray(log.events) ? log.events : []
  const callNames = new Map                ()
  const conclusions                                       = []
  const errors                 = []
  const successes                 = []
  const toolNames = new Set        ()
  let turns = 0
  let boundarySeq = 0

  for (const raw of events) {
    if (raw === null || typeof raw !== 'object') continue
    const event = raw                                               
    const seq = Number(event.seq ?? 0)
    boundarySeq = Math.max(boundarySeq, seq)
    if (event.type === 'turn/start') turns += 1
    if (event.type === 'tool/call') {
      const name = typeof event.data?.name === 'string' ? event.data.name : ''
      const callId = typeof event.data?.callId === 'string' ? event.data.callId : ''
      if (name.length > 0) toolNames.add(name)
      if (callId.length > 0 && name.length > 0) callNames.set(callId, name)
      continue
    }
    if (event.type === 'tool/result') {
      const message = event.data?.message
      const isError = message?.isError === true || event.data?.error !== undefined
      const callId = message?.source?.callId ?? message?.toolCallId
      const tool = typeof callId === 'string' ? callNames.get(callId) : undefined
      const text = textOf(message).split(/\r?\n/u).map((line) => line.trim()).find((line) => line.length > 0) ?? ''
      if (text.length === 0) continue
      if (!isError) {
        successes.push({ ...(tool === undefined ? {} : { tool }), text: text.slice(0, 160), seq })
        continue
      }
      errors.push({ ...(tool === undefined ? {} : { tool }), text: text.slice(0, 240), seq })
      continue
    }
    if (event.type === 'assistant/message') {
      const text = textOf(event.data?.message)
      if (text.length > 0) conclusions.push({ text: conclusionOf(text), seq })
      continue
    }
    if (event.type === 'user/message') {
      const kind = event.data?.source?.kind
      // v0.32 P2: allowlist, not denylist — an unknown producer is injected.
      if (!isHumanSourceKind(kind)) continue
      // The user's own words are not mined for skills in M1; the goal of the
      // session is already in its log and reachable by seq.
      continue
    }
  }

  // 20 × 1200 chars worst case: enough for the closing summaries, still a bounded
// prompt (the extractor's budget is 4000 output tokens).
  const keptConclusions = conclusions.slice(-20)
  const keptErrors = errors.slice(-10)
  const keptSuccesses = successes.slice(-10)
  const evidence = [
    ...new Set([
      ...keptConclusions.map((item) => item.seq),
      ...keptErrors.map((item) => item.seq ?? 0),
      ...keptSuccesses.map((item) => item.seq ?? 0),
    ]),
  ].filter((seq) => seq > 0)

  return {
    sessionId,
    boundarySeq,
    turns,
    conclusions: keptConclusions,
    errors: keptErrors,
    successes: keptSuccesses,
    toolNames: [...toolNames].slice(0, 20),
    evidence,
  }
}

/** A compact transcript for the extraction prompt (bounded, seq-labelled). */
export function renderEpisode(episode         )         {
  const lines           = [
    `session: ${episode.sessionId}`,
    `turns: ${episode.turns}`,
    `tools used: ${episode.toolNames.join(', ') || '(none)'}`,
    '',
    'ASSISTANT CONCLUSIONS (newest last, with seq):',
    ...episode.conclusions.map((item) => `- [seq ${item.seq}] ${item.text}`),
  ]
  if (episode.errors.length > 0) {
    lines.push('', 'FAILURES (tool, first line, seq):')
    for (const error of episode.errors) {
      lines.push(`- [seq ${error.seq ?? '?'}] ${error.tool ?? 'tool'}: ${error.text}`)
    }
  }
  // v0.6: cite-able successes. A skill's evidence must include one of these; the
  // verifier re-opens each cited seq in the real log and refuses narration-only
  // evidence, so the prompt has to show the model where the proof lives.
  if ((episode.successes ?? []).length > 0) {
    lines.push('', 'SUCCESSFUL TOOL RESULTS (tool, first line, seq — cite these to prove an operation worked):')
    for (const success of episode.successes ?? []) {
      lines.push(`- [seq ${success.seq ?? '?'}] ${success.tool ?? 'tool'}: ${success.text}`)
    }
  }
  return lines.join('\n')
}
/**
 * The provider/model this session actually ran on.
 *
 * Measured live: calling `llm.stream()` without a provider fails with
 * `no adapter registered for provider "undefined"` — the host does not infer a
 * default from the calling plugin. The log always records the answer
 * (`request/context`, `model/selection`, or the session header), so read it.
 */
                              
                   
                
 

export function resolveModelTarget(log                                           )              {
  const events = Array.isArray(log.events) ? log.events : []
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index]                                             
    if (event === undefined) continue
    if (event.type === 'request/context' || event.type === 'model/selection') {
      const provider = event.data?.provider
      const model = event.data?.model
      if (typeof provider === 'string' && provider.length > 0) {
        return { provider, ...(typeof model === 'string' && model.length > 0 ? { model } : {}) }
      }
    }
  }
  const session = (log.session ?? {})                           
  const provider = typeof session.provider === 'string' ? session.provider : undefined
  const model = typeof session.model === 'string' ? session.model : undefined
  return { ...(provider === undefined ? {} : { provider }), ...(model === undefined ? {} : { model }) }
}
